import com.github.javaparser.JavaParser;
import com.github.javaparser.ParserConfiguration;
import com.github.javaparser.ast.CompilationUnit;
import com.github.javaparser.ast.expr.MethodCallExpr;
import com.github.javaparser.symbolsolver.javaparsermodel.JavaParserFacade;
import com.github.javaparser.symbolsolver.resolution.typesolvers.ReflectionTypeSolver;

public class VerifyTextBlock {
    public static void main(String[] args) {
        String src = "public class MyExample {\n" +
            "  public static void main(String[] args) {\n" +
            "    \"Hello single %s!\".formatted(\"world\");\n" +
            "    \"\"\"\n" +
            "        Hello multiple %s!\n" +
            "        \"\"\".formatted(\"world\");\n" +
            "  }\n" +
            "}\n";
        ParserConfiguration config = new ParserConfiguration();
        config.setLanguageLevel(ParserConfiguration.LanguageLevel.JAVA_21);
        config.setSymbolResolver(new com.github.javaparser.symbolsolver.JavaSymbolSolver(new ReflectionTypeSolver(false)));
        CompilationUnit cu = new JavaParser(config).parse(src).getResult().get();
        for (MethodCallExpr n : cu.findAll(MethodCallExpr.class)) {
            var solved = JavaParserFacade.get(new ReflectionTypeSolver(false)).solve(n);
            System.out.println("solved=" + solved.isSolved() + " : " + solved.getCorrespondingDeclaration().getQualifiedSignature() + " <- " + n.toString().replace("\n", "\\n"));
        }
    }
}
EOF
